import { 场地表, 结算打工 } from '../../脚本/面板数据';

/* 本地自测入口（不参与角色卡导出）。
 *
 * 打开 dist/知夏/界面/_自测/自测.html 时它会：开一局 → 点一次选项 → 点收工 → 读变量核对。
 * 目的只有一个：在进酒馆之前确认「点小游戏 → 得分 → 结算 → 写回变量」这条链没断。
 * 它替代不了实机，但能在几秒内抓到接错接口、事件没接上这类硬错误。
 *
 * 注意：面板的 store 在页面加载时就按当时的变量建好了，所以自测不去改假变量的初始局面，
 * 直接按假局面本身能不能开工来决定走哪条路（那一份局面是「夜里 + 夜市 + 够解锁」）。
 */
const 框 = document.getElementById('自测结果') as HTMLElement;
let 报过 = false;

function 报(话: string) {
  框.style.display = 'block';
  框.textContent += 话 + '\n';
}

const 变量 = () => (window as any).__预览变量.stat_data;
const 起点 = JSON.parse(JSON.stringify(变量()));

window.setTimeout(() => {
  框.style.cssText =
    'position:fixed;left:0;right:0;bottom:0;max-height:45%;overflow:auto;padding:10px 12px;background:#1f2a24;color:#cfe8d4;font:12px/1.5 monospace;white-space:pre-wrap;z-index:9999';

  报('起点：钱 ' + 起点.钱 + '，体力 ' + 起点.哥哥.体力 + '，场景 ' + 起点.场景.地点 + '，可打工 ' + 起点.场景.可打工);
  报('此刻页面上的按钮：' + [...document.querySelectorAll('button')].map(b => b.textContent?.trim()).join(' / ') || '（一个都没有）');
  报('#app 的字节数：' + (document.getElementById('app')?.innerHTML.length ?? 0));

  // 第一步：先确认写回接口本身通不通，把「接口没接上」和「按钮没接上」分开。
  try {
    (window as any).updateVariablesWith((表: any) => {
      表.stat_data.钱 = 999;
      return 表;
    }, { type: 'message', message_id: 0 });
    报('写回接口：' + (变量().钱 === 999 ? '通' : '不通（写了 999，读回 ' + 变量().钱 + '）'));
  } catch (错误) {
    报('写回接口抛错：' + (错误 as Error).message);
  }

  // 第二步：走界面。点开工，再立刻点收工，让这一局结算掉。
  window.setTimeout(点开工, 500);
}, 800);

function 点开工() {
  const 按钮们 = [...document.querySelectorAll('button')];
  const 开工 = 按钮们.find(按钮 => 按钮.textContent?.trim() === '开工') as HTMLButtonElement | undefined;
  if (!开工) {
    报('没找到「开工」按钮。页面上现有按钮：' + 按钮们.map(b => b.textContent?.trim()).join(' / '));
    对比();
    return;
  }
  报('点了「开工」，现场有 ' + 按钮们.filter(b => b.textContent?.trim() === '开工').length + ' 个可开工的活。');
  开工.click();
  window.setTimeout(点收工, 700);
}

function 点收工() {
  const 收工 = [...document.querySelectorAll('button')].find(按钮 => 按钮.textContent?.trim() === '收工') as
    | HTMLButtonElement
    | undefined;
  if (!收工) {
    报('没找到「收工」按钮，说明小游戏框没渲染出来。');
    对比();
    return;
  }
  收工.click();
  报('点了「收工」。');
  window.setTimeout(() => 对比(), 800);
}

function 对比() {
  if (报过) return;
  报过 = true;
  const 现在 = 变量();
  报('');
  报('面板回执：' + (document.querySelector('.zx-receipt')?.textContent?.trim() ?? '（没有回执，说明结算没走到）'));
  报('写回次数：' + ((window as any).__写回次数 ?? 0));
  报('钱：' + 起点.钱 + ' → ' + 现在.钱 + '（这里要看的是不是 999，999 说明第一步的写回还在）');
  报('体力：' + 起点.哥哥.体力 + ' → ' + 现在.哥哥.体力);
  报('今日已打工：' + 现在.哥哥.今日已打工);
  报('上次结算：' + 现在.$进度.上次结算);
  const 任一场地 = Object.keys(场地表).find(名 => Number(现在.$进度.次数[名] ?? 0) > 0);
  if (任一场地) {
    const 活的 = Object.values(场地表[任一场地].活)[0];
    报(
      '结算核对：' +
        任一场地 +
        ' 做过 ' +
        现在.$进度.次数[任一场地] +
        ' 次，熟练 ' +
        现在.$进度.熟练[任一场地] +
        '；该场地一次活扣 ' +
        活的.体力 +
        ' 点体力，收入区间 ' +
        结算打工({ 时薪: 活的.时薪, 题数: 活的.题数, 得分: 0, 体力: 80, 熟练: 0, 原有体力消耗: 活的.体力 }).收入 +
        ' 起。',
    );
  } else {
    报('结算核对：没有任何场地的次数被加过，结算没写回。');
  }
}

window.setTimeout(() => {
  if (!报过) 对比();
}, 9000);
